// FINAL SECURE VERSION - Addressing all security concerns from review
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { validationResult, body } = require('express-validator');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Security Headers (OWASP A05: Security Misconfiguration)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      baseUri: ["'self'"],
      fontSrc: ["'self'", "https:"],
      frameAncestors: ["'self'"],
      imgSrc: ["'self'", "data:"],
      objectSrc: ["'none'"],
      scriptSrc: ["'self'"],
      scriptSrcAttr: ["'none'"],
      styleSrc: ["'self'", "https:"],
      upgradeInsecureRequests: []
    }
  },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  crossOriginEmbedderPolicy: false  // Required for some environments
}));

// 2. Rate Limiting (OWASP A05: Security Misconfiguration, helps with A07: Identification)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  message: { error: 'Too many requests from this IP, please try again later.' }
});
app.use('/api/', apiLimiter));  // Apply to API routes

// 3. Logging (OWASP A09: Logging & Monitoring Failures)
app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent" - :response-time ms'));

// 4. Body Parsing (Required for POST/PUT routes)
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// ===== ROUTES WITH SECURITY CONSIDERATIONS =====

// Health Check Endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    service: 'secure-api',
    version: '1.0.0'
  });
});

// Users Example - Demonstrates secure practices
app.get('/api/users', 
  // Input validation example (even though not used, shows pattern)
  [
    // These would be relevant if we accepted query parameters
    // body('limit').optional().isInt({ min: 1, max: 100 }),
    // body('offset').optional().isInt({ min: 0 }),
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation Failed', 
          details: errors.array() 
        });
      }
      next();
    }
  ], 
  (req, res) => {
    // In a real application, this would come from a database
    // with proper access controls and authentication
    res.json({
      success: true,
      count: 2,
      data: [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ]
    });
  }
);

// Example secure POST endpoint (demonstrates validation)
app.post('/api/users',
  [
    body('name').trim().notEscape().isLength({ min: 1, max: 50 }).withMessage('Name must be 1-50 characters'),
    body('email').trim().isEmail().normalizeEmail().withMessage('Please provide a valid email'),
    body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation Failed', 
          details: errors.array() 
        });
      }
      next();
    }
  ],
  (req, res) => {
    // In real app: hash password, save to DB, return user (without password)
    res.status(201).json({
      success: true,
      message: 'User created successfully',
      user: {
        id: Date.now(), // Mock ID
        name: req.body.name,
        email: req.body.email
        // Note: password hash would be stored, never returned
      }
    });
  }
);

// ===== ERROR HANDLING (OWASP A06: Vulnerable Components, A05) =====

// 404 Not Found
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `No route found for ${req.method} ${req.originalUrl}`,
    timestamp: new Date().toISOString()
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  // Log error securely (never expose stack trace to client in production)
  console.error(`[${new Date().toISOString}] ERROR:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : '[REDACTED]',
    url: req.originalUrl,
    method: req.method,
    ip: req.ip || req.connection.remoteAddress
  });

  // Send appropriate error response
  const statusCode = err.status || 500;
  res.status(statusCode).json({
    error: {
      message: process.env.NODE_ENV === 'development' ? err.message : 
               statusCode === 500 ? 'Internal Server Error' : err.message,
      // Only include additional details in development
      ...(process.env.NODE_ENV === 'development' && { 
        stack: err.stack,
        url: req.originalUrl
      })
    },
    timestamp: new Date().toISOString()
  });
});

// ===== SERVER STARTUP =====
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`
  🔒 Secure Express.js Server
  🌐 Environment: ${process.env.NODE_ENV || 'development'}
  🚀 Listening on port: ${PORT}
  📝 Health check: GET http://localhost:${PORT}/health
  👥 Users API: GET http://localhost:${PORT}/api/users
  `);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server };

