// Secured Express.js Application
// Implements security best practices for OWASP Top 10 protection

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// Security Middleware
app.use(helmet());
app.use(express.json());

// CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: {
    error: 'Too many requests from this IP, please try again later after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Authentication Middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: { message: 'Access token required' } });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      return res.status(403).json({ error: { message: 'Invalid or expired token' } });
    }
    req.user = user;
    next();
  });
}

// Input Validation Middleware
const validateUserId = [
  body('id').isInt({ gt: 0 }).withMessage('User ID must be a positive integer'),
  body('id').trim().escape(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {
  // In a real app, you might filter users based on req.user permissions
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.get('/users/:id', validateUserId, authenticateToken, (req, res) => {
  const userId = parseInt(req.params.id);

  // Simulate database lookup
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: { message: 'User not found' } });
  }

  // In a real app, check if the authenticated user is authorized to view this user
  res.json(user);
});

// Example login endpoint (for demonstration)
app.post('/login', 
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 6 }),
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }
      next();
    }
  ],
  (req, res) => {
    const { email, password } = req.body;

    // In a real app, validate against database
    // This is just for demonstration
    if (email === 'alice@example.com' && password === 'password123') {
      const user = { id: 1, email: 'alice@example.com', name: 'Alice' };
      const accessToken = jwt.sign(
        user, 
        process.env.ACCESS_TOKEN_SECRET || 'your-secret-key', 
        { expiresIn: '1h' }
      );

      res.json({ accessToken });
    } else {
      res.status(401).json({ error: { message: 'Invalid credentials' } });
    }
  }
);

// Error Handling Middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  const statusCode = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({
    error: {
      message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  });
});

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: { message: 'Route not found' }
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

